 g.fillStyle='#252b23';g.fillRect(19,31,9,13);g.fillRect(18,34,12,2);g.fillStyle=light;g.fillRect(20,32,1,1);g.fillRect(20,36,1,1);g.fillRect(28,30,3,2);
 // brazo y cuello
 g.fillStyle=skin;g.fillRect(19,20,10,7);g.fillStyle=green;g.fillRect(20,21,8,5);g.fillStyle=dark;g.fillRect(5,35,7,9);g.fillRect(36,34,7,9);
 // cara, casco
 g.fillStyle='#292923';g.fillRect(15,8,18,15);g.fillStyle=skin;g.fillRect(17,11,14,12);g.fillStyle='#292b25';g.fillRect(19,15,3,2);g.fillRect(27,15,3,2);g.fillRect(22,20,5,1);
