 // pack and small unit marking
 g.fillStyle=dark;g.fillRect(35,25,7,12);g.fillStyle=variant===0?'#d8f56a':'#d56b50';g.fillRect(14,28,3,4);
 return c}
const sprites=[soldierSprite(0),soldierSprite(1)];
function floorAndSky(horizon){const sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#262d29');sky.addColorStop(.7,'#667067');sky.addColorStop(1,'#a79c7e');ctx.fillStyle=sky;ctx.fillRect(0,0,W,horizon);ctx.fillStyle='#5e5546';ctx.fillRect(0,horizon,W,H-horizon);
// perspective road surface with dusty block pattern
const img=ctx.createImageData(W,H-horizon),d=img.data;for(let y=0;y<H-horizon;y++){const yy=y+horizon,dist=H*.48/Math.max(1,yy-horizon);for(let x=0;x<W;x+=1){const a=player.a+Math.atan((x-W/2)/(W*.86)),wx=player.x+Math.cos(a)*dist,wy=player.y+Math.sin(a)*dist;const grout=(Math.abs((wx%1)-.5)>.475||Math.abs((wy%1)-.5)>.475),hash=(Math.floor(wx*8)*17+Math.floor(wy*8)*31)&7,shade=Math.max(.35,1-dist*.055)*(grout?.62:.87+hash*.018);const i=(y*W+x)*4;d[i]=Math.min(255,111*shade);d[i+1]=Math.min(255,100*shade);d[i+2]=Math.min(255,79*shade);d[i+3]=255}}ctx.putImageData(img,0,horizon)}
function castWalls(horizon){const step=2;for(let sx=0;sx<W;sx+=step){const ray=player.a+Math.atan((sx-W/2)/(W*.86)),rx=Math.cos(ray),ry=Math.sin(ray);let mx=Math.floor(player.x),my=Math.floor(player.y),ddx=Math.abs(1/rx),ddy=Math.abs(1/ry),sxstep, systep,sdx,sdy;if(rx<0){sxstep=-1;sdx=(player.x-mx)*ddx}else{sxstep=1;sdx=(mx+1-player.x)*ddx}if(ry<0){systep=-1;sdy=(player.y-my)*ddy}else{systep=1;sdy=(my+1-player.y)*ddy}let side=0;for(let i=0;i<32;i++){if(sdx<sdy){sdx+=ddx;mx+=sxstep;side=0}else{sdy+=ddy;my+=systep;side=1}if((map[my]||'')[mx]==='1')break}let dist=side===0?sdx-ddx:sdy-ddy;dist=Math.max(.12,dist);const wallH=Math.min(H*2,H*.88/dist),top=Math.max(horizon,Math.floor(horizon-wallH*.52)),bottom=Math.min(H,Math.floor(horizon+wallH*.48));let u=side===0?player.y+dist*ry:player.x+dist*rx;u-=Math.floor(u);const edge=Math.min(u,1-u),brickLine=(Math.floor((horizon-(top))*11/wallH)%4===0)||(edge<.025);let base;if(brickLine)base=[75,71,61];else if(side)base=[100,99,84];else base=[122,119,99];const tile=(Math.floor(u*12)+mx*3+my*7)%11;if(tile===2||tile===3){base=side?[53,68,67]:[61,78,74]}const shade=Math.max(.36,1-dist*.063)*(side?.77:1);for(let x=sx;x<Math.min(W,sx+step);x++){depth[x]=dist;depth[x+1]=dist}for(let y=top;y<bottom;y++){const v=(y-top)/Math.max(1,bottom-top),seam=(Math.floor(v*12)%4===0&&u>.08&&u<.92),window=(tile===2||tile===3)&&v>.16&&v<.78,glow=window&&((Math.floor(v*7)+mx+my)%4===0);let r=base[0],g=base[1],b=base[2];if(seam){r*=.53;g*=.53;b*=.53}if(window){r=glow?111:29;g=glow?124:43;b=glow?103:42}const fog=Math.min(.55,dist*.025);r=r*shade*(1-fog)+75*fog;g=g*shade*(1-fog)+83*fog;b=b*shade*(1-fog)+77*fog;ctx.fillStyle=`rgb(${r|0},${g|0},${b|0})`;ctx.fillRect(sx,y,step,1)}}}
function spriteDraw(sx,sy,image,dist,kind,horizon,alpha=1){const dx=sx-player.x,dy=sy-player.y,ang=norm(Math.atan2(dy,dx)-player.a);if(Math.abs(ang)>FOV*.72||dist<.15)return;const screen=W/2+Math.tan(ang)*(W*.86),height=Math.min(H*1.6,H*.70/dist),width=height*(image.width/image.height),top=horizon-height*.52,left=screen-width*.5;if(left>W||left+width<0)return;ctx.globalAlpha=alpha;ctx.drawImage(image,left,top,width,height);ctx.globalAlpha=1;
// wall occlusion by restoring wall slices over sprite
for(let x=Math.max(0,Math.floor(left));x<Math.min(W,Math.ceil(left+width));x++){if(dist>depth[x]){const xx=x;const ray=player.a+Math.atan((xx-W/2)/(W*.86)),rx=Math.cos(ray),ry=Math.sin(ray);let mx=Math.floor(player.x),my=Math.floor(player.y),ddx=Math.abs(1/rx),ddy=Math.abs(1/ry),sxstep, systep,sdx,sdy;if(rx<0){sxstep=-1;sdx=(player.x-mx)*ddx}else{sxstep=1;sdx=(mx+1-player.x)*ddx}if(ry<0){systep=-1;sdy=(player.y-my)*ddy}else{systep=1;sdy=(my+1-player.y)*ddy}let side=0;for(let i=0;i<32;i++){if(sdx<sdy){sdx+=ddx;mx+=sxstep;side=0}else{sdy+=ddy;my+=systep;side=1}if((map[my]||'')[mx]==='1')break}const wd=side===0?sdx-ddx:sdy-ddy,wh=Math.min(H*2,H*.88/wd),wt=Math.max(horizon,Math.floor(horizon-wh*.52)),wb=Math.min(H,Math.floor(horizon+wh*.48));ctx.fillStyle='#292f2b';ctx.fillRect(x,wt,1,wb-wt)}}
}

function clearShot(x1,y1,x2,y2){const dx=x2-x1,dy=y2-y1,n=Math.ceil(Math.hypot(dx,dy)*12);for(let i=1;i<n;i++){const t=i/n;if(cell(x1+dx*t,y1+dy*t))return false}return true}
let audio=null;function beep(type){try{audio??=new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);const t=audio.currentTime;o.type='sawtooth';o.frequency.setValueAtTime(type==='shot'?125:type==='hit'?490:220,t);o.frequency.exponentialRampToValueAtTime(type==='shot'?42:type==='hit'?230:150,t+.11);g.gain.setValueAtTime(type==='shot'?.045:.025,t);g.gain.exponentialRampToValueAtTime(.001,t+.13);o.start(t);o.stop(t+.14)}catch(e){}}
function shoot(){if(!running||reloading||shotCooldown>0)return;if(player.ammo<=0){showToast('SIN MUNICIÓN — R PARA RECARGAR');shotCooldown=.2;return}player.ammo--;shotCooldown=.19;flash=.075;beep('shot');let target=null,best=.105;for(const e of enemies){if(!e.alive)continue;const d=Math.hypot(e.x-player.x,e.y-player.y),a=Math.abs(norm(Math.atan2(e.y-player.y,e.x-player.x)-player.a)),tolerance=Math.max(.035,Math.min(.10,.30/d));if(a<tolerance&&a<best&&clearShot(player.x,player.y,e.x,e.y)){best=a;target=e}}if(target){target.hp-=52;target.hurt=.16;beep('hit');if(target.hp<=0){target.alive=false;player.kills++;showToast('HOSTIL NEUTRALIZADO');if(player.kills===8)setTimeout(()=>{if(running)endScreen(true)},550)}}syncHud()}
function damage(amount){const absorbed=Math.min(player.armor,Math.ceil(amount*.65));player.armor-=absorbed;player.hp-=amount-absorbed;damageFlash=.22;beep('damage');if(player.hp<=0){player.hp=0;syncHud();setTimeout(()=>endScreen(false),380)}syncHud()}
function update(dt){shotCooldown=Math.max(0,shotCooldown-dt);flash=Math.max(0,flash-dt);damageFlash=Math.max(0,damageFlash-dt);toastT=Math.max(0,toastT-dt);if(toastT<=0)$('toast').classList.remove('show');if(reloading){reloadT-=dt;if(reloadT<=0){const n=Math.min(30-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;reloading=false;$('reload').classList.add('hidden');showToast('CARGADOR LISTO')}}if(fireHeld)shoot();
let f=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),s=(keys.KeyD?1:0)-(keys.KeyA?1:0);if(keys.ArrowLeft)player.a-=dt*1.7;if(keys.ArrowRight)player.a+=dt*1.7;if(f||s){const n=Math.hypot(f,s)||1,v=dt*2.7;const vx=(Math.cos(player.a)*f+Math.cos(player.a+Math.PI/2)*s)/n*v,vy=(Math.sin(player.a)*f+Math.sin(player.a+Math.PI/2)*s)/n*v;if(free(player.x+vx,player.y,.2))player.x+=vx;if(free(player.x,player.y+vy,.2))player.y+=vy;walk+=dt*11}
for(const e of enemies){if(!e.alive)continue;e.hurt=Math.max(0,e.hurt-dt);e.cool-=dt;const d=Math.hypot(player.x-e.x,player.y-e.y);if(d<9){if(d>2.5){const v=dt*.48,dx=(player.x-e.x)/d*v,dy=(player.y-e.y)/d*v;if(free(e.x+dx,e.y,.18))e.x+=dx;if(free(e.x,e.y+dy,.18))e.y+=dy;e.move+=dt*7}if(d<7&&e.cool<=0&&clearShot(e.x,e.y,player.x,player.y)){e.cool=1.3+Math.random()*1.25;if(Math.random()<Math.max(.18,.56-d*.045))damage(7+Math.floor(Math.random()*7))}}}
for(const p of pickups){if(p.on&&Math.hypot(player.x-p.x,player.y-p.y)<.58){p.on=false;if(p.type==='health'){player.hp=Math.min(100,player.hp+30);showToast('BOTIQUÍN +30 SALUD')}else{player.reserve=Math.min(180,player.reserve+45);showToast('MUNICIÓN +45')}syncHud()}}
}
function syncHud(){$('health').innerHTML=`${Math.ceil(player.hp)}<small> %</small>`;$('armor').innerHTML=`${Math.ceil(player.armor)}<small> %</small>`;$('ammo').textContent=player.ammo;$('reserve').textContent=player.reserve;$('objectiveCount').textContent=`HOSTILES ${player.kills}/8`; $('hit').classList.toggle('on',damageFlash>0)}
function drawPickup(p,horizon){const d=Math.hypot(p.x-player.x,p.y-player.y);if(d<.3)return;const a=norm(Math.atan2(p.y-player.y,p.x-player.x)-player.a),screen=W/2+Math.tan(a)*(W*.86),size=Math.min(45,28/d*3),y=horizon+size*.7;if(screen<0||screen>W||d>depth[Math.max(0,Math.min(W-1,screen|0))])return;ctx.save();ctx.translate(screen,y);ctx.fillStyle=p.type==='health'?'#d8f56a':'#d6bd69';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=12;ctx.fillRect(-size*.3,-size*.6,size*.6,size*.6);ctx.shadowBlur=0;ctx.fillStyle='#252b20';if(p.type==='health'){ctx.fillRect(-2,-size*.52,4,size*.43);ctx.fillRect(-size*.2,-size*.37,size*.4,4)}else{for(let i=0;i<3;i++)ctx.fillRect(-size*.2+i*size*.2,-size*.48,size*.08,size*.34)}ctx.restore()}
function drawGun(){const bob=Math.sin(walk)*3, recoil=flash>0?13:0;ctx.save();ctx.translate(W/2, H+12+bob+recoil);ctx.fillStyle='#121511';ctx.beginPath();ctx.moveTo(-92,0);ctx.lineTo(-72,-73);ctx.lineTo(-47,-95);ctx.lineTo(43,-95);ctx.lineTo(80,-66);ctx.lineTo(99,0);ctx.closePath();ctx.fill();ctx.fillStyle='#343a32';ctx.beginPath();ctx.moveTo(-60,0);ctx.lineTo(-42,-73);ctx.lineTo(35,-74);ctx.lineTo(64,0);ctx.fill();ctx.fillStyle='#555a4b';ctx.fillRect(-38,-81,71,8);ctx.fillStyle='#1b201a';ctx.fillRect(-18,-92,43,15);ctx.fillStyle='#78806a';ctx.fillRect(-12,-88,31,3);ctx.fillStyle='#292e26';ctx.fillRect(37,-65,11,45);ctx.fillStyle='#666b58';ctx.fillRect(-8,-98,18,4);ctx.fillStyle='#161a15';ctx.fillRect(-5,-113,10,17);if(flash>0){ctx.globalAlpha=flash/.075;ctx.fillStyle='#fff0a8';ctx.beginPath();ctx.moveTo(-17,-104);ctx.lineTo(0,-153);ctx.lineTo(17,-104);ctx.lineTo(7,-112);ctx.lineTo(0,-129);ctx.lineTo(-7,-112);ctx.closePath();ctx.fill();ctx.globalAlpha=1}ctx.restore()}
function drawMini(){const size=94,scale=size/16,x=W-size-15,y=15;ctx.save();ctx.globalAlpha=.83;ctx.fillStyle='#111710';ctx.fillRect(x-5,y-5,size+10,size+10);for(let my=0;my<16;my++)for(let mx=0;mx<16;mx++){ctx.fillStyle=map[my][mx]==='1'?'#53594b':'#242b23';ctx.fillRect(x+mx*scale/16,y+my*scale/16,scale/16+.3,scale/16+.3)}for(const e of enemies)if(e.alive){ctx.fillStyle='#ee6859';ctx.fillRect(x+e.x*scale/16-1.5,y+e.y*scale/16-1.5,3,3)}for(const p of pickups)if(p.on){ctx.fillStyle='#d8f56a';ctx.fillRect(x+p.x*scale/16-1,y+p.y*scale/16-1,2,2)}ctx.fillStyle='#e7f2ce';ctx.beginPath();ctx.arc(x+player.x*scale/16,y+player.y*scale/16,3,0,TAU);ctx.fill();ctx.strokeStyle='#e7f2ce';ctx.beginPath();ctx.moveTo(x+player.x*scale/16,y+player.y*scale/16);ctx.lineTo(x+(player.x+Math.cos(player.a)*.8)*scale/16,y+(player.y+Math.sin(player.a)*.8)*scale/16);ctx.stroke();ctx.restore()}
function render(){const horizon=Math.round(H*.48+Math.sin(walk)*1.5);floorAndSky(horizon);castWalls(horizon);const all=[];for(const e of enemies)if(e.alive)all.push({x:e.x,y:e.y,d:Math.hypot(e.x-player.x,e.y-player.y),e});all.sort((a,b)=>b.d-a.d);for(const q of all){const e=q.e; spriteDraw(e.x,e.y,sprites[e.hurt>0?1:0],q.d,0,horizon);if(e.hurt>0){const angle=norm(Math.atan2(e.y-player.y,e.x-player.x)-player.a),sx=W/2+Math.tan(angle)*(W*.86),hh=Math.min(H,H*.7/q.d);ctx.fillStyle='#e76b58';ctx.fillRect(sx-hh*.17,horizon-hh*.52-7,hh*.34,3);ctx.fillStyle='#20251e';ctx.fillRect(sx-hh*.17,horizon-hh*.52-7,hh*.34*(e.hp/100),3)}}for(const p of pickups)if(p.on)drawPickup(p,horizon);drawGun();drawMini();if(damageFlash>0){ctx.fillStyle=`rgba(210,38,29,${damageFlash*.28})`;ctx.fillRect(0,0,W,H)}if(flash>0){ctx.fillStyle=`rgba(255,230,150,${flash*1.4})`;ctx.fillRect(W/2-2,H/2-2,4,4)}}
function loop(t){if(!running)return;const dt=Math.min(.05,(t-last)/1000||0);last=t;update(dt);render();requestAnimationFrame(loop)}
makeMap();syncHud();render();
})();
